INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('1', '马王堆素纱单衣', '秦汉', '湖南长沙', '28.21', '112.97', '湖南博物院', '/images/relics/relic_han_susha.png', '西汉早期素纱单衣，重仅49克，迄今所见最轻丝织衣物');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('2', '黄昇墓出土褙子', '宋', '福建福州', '26.08', '119.3', '福建省博物馆', '/images/relics/relic_song_beizi.png', '南宋贵族女子服饰，出土大量罗、纱织物与纹样');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('3', '定陵织金妆花缎', '明', '北京昌平', '40.3', '116.22', '明十三陵博物馆', '/images/relics/relic_geo_dingling_zhuanghua.png', '明万历帝后织金妆花缎龙袍，织造工艺登峰造极');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('4', '敦煌供养人像壁画', '隋唐', '甘肃敦煌', '40.04', '94.81', '敦煌研究院', '/images/relics/relic_geo_dunhuang_tang.png', '唐代供养人服饰形象，反映大袖襦裙与圆领袍');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('5', '集宁路织金锦', '元', '内蒙古集宁', '41.03', '113.11', '内蒙古博物院', '/images/relics/relic_geo_jininglu_zhijin.png', '元代纳石失（织金锦）实物，见证丝路织造交流');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('6', '马山一号楚墓丝袍', '先秦', '湖北荆州', '30.35', '112.19', '荆州博物馆', '/images/relics/relic_xianqin_fengniaoxiu.png', '战国楚墓出土丝织品，深衣形制实证');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('7', '马王堆信期绣丝绵袍', '秦汉', '长沙马王堆一号汉墓', '28.22', '112.98', '湖南博物院', '/images/relics/relic_han_xinqixiu.png', '褐色菱纹罗地"信期绣"丝绵袍，衣长150厘米，通袖长250厘米，袖口28厘米，腰宽60厘米。信期绣为马王堆汉墓三大名绣之一，纹样如卷曲蔓草与穗状流云，寓意燕归如期。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('8', '马王堆印花敷彩丝绵袍', '秦汉', '长沙马王堆一号汉墓', '28.22', '112.99', '湖南博物院', '/images/relics/relic_han_yinhuafucai.png', '印花敷彩纱丝绵袍，交领右衽直裾式，袖通长250厘米，身长129厘米。印花与彩绘结合，朱红、粉白、墨黑三色藤本植物纹，西汉贵族时装珍品。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('9', '隆化鸽子洞辫线袄', '元', '河北隆化鸽子洞', '41.31', '117.74', '中国丝绸博物馆', '/images/relics/relic_yuan_bianxianao.png', '元代蒙古男子袍服，绫、绢材质，交领窄袖，腰间缝缀辫线收束，腰下打细褶如裙。北方游牧骑射服饰的典型实物。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('10', '孔府旧藏桃红纱大袖衫', '明', '山东曲阜孔府', '35.59', '116.99', '孔子博物馆', '/images/relics/relic_geo_kongfu_daxiushan.png', '桃红纱地彩绣花鸟纹大袖衫，明代女装大袖衫实物，纱地轻薄通透，彩绣花鸟纹样繁密，孔府旧藏明代服饰之代表。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('11', '秦陵铠甲武士俑服饰', '先秦', '陕西西安', '34.38', '109.26', '秦始皇兵马俑博物馆', '/images/relics/relic_geo_qin_jiayi.png', '陶俑甲片编缀再现秦军戎装：札甲、鱼鳞甲并用，甲片铆接，肩臂分片，是秦代军戎服制的直接物证。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('12', '信阳长台关楚墓丝织品', '先秦', '河南信阳', '32.13', '114.09', '河南博物院', '/images/relics/relic_geo_xinyang_beiwenqi.png', '出土菱纹罗、凤纹绣等楚国丝织实物，见证战国楚地织绣工艺之盛，衣袍形制与马山楚墓互为印证。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('13', '永泰公主墓壁画侍女半臂', '隋唐', '陕西乾县', '34.53', '108.24', '乾陵博物馆', '/images/relics/relic_tang_banbi.png', '墓道壁画侍女着窄袖短襦、外罩半臂、下着长裙披帛，是唐代宫廷女性日常装束的直观图像证据。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('14', '苏州虎丘塔出土宋代丝织品', '宋', '江苏苏州', '31.32', '120.62', '苏州博物馆', '/images/relics/relic_geo_huqiuta_cixiu.png', '虎丘塔窖藏出土宋代绢、绫、罗等织物，纹样清雅，印证宋代织造技术与服饰面料的精细。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('15', '黄岩南宋赵伯澐墓丝绸', '宋', '浙江台州黄岩', '28.64', '121.26', '黄岩博物馆', '/images/relics/relic_geo_zhaoboyun_daxiushan.png', '南宋赵伯澐墓出土对襟褙子、罗衫等成组服饰，面料轻薄透气，纹样疏朗，是宋代士人服饰的重要实物。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('16', '德安南宋周氏墓丝绸', '宋', '江西德安', '29.33', '115.76', '德安县博物馆', '/images/relics/relic_geo_dean_sanjianqun.png', '南宋周氏墓出土大袖袍、罗衫等丝绸服饰，反映宋代女子礼服形制与织绣工艺。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('17', '成都老官山汉墓提花织机', '秦汉', '四川成都', '30.66', '104.08', '成都博物馆', '/images/relics/relic_geo_laoguanshan_zhiji.png', '出土四部西汉提花织机模型与丝织品，复原汉代织造技术，印证蜀锦之源的纺织盛况。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('18', '吐鲁番阿斯塔那联珠对马纹锦', '隋唐', '新疆吐鲁番', '42.95', '89.19', '新疆维吾尔自治区博物馆', '/images/relics/relic_geo_astana_duima.png', '阿斯塔那古墓群出土联珠对马纹锦袍，是丝绸之路东西织造技术与纹样交流的直接见证。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('19', '太原北齐娄睿墓壁画衣冠', '魏晋', '山西太原', '37.86', '112.75', '山西博物院', '/images/relics/relic_weijin_kuanshan.png', '娄睿墓壁画绘北齐贵族出行、宴乐场景，人物着鲜卑风格服饰与汉式袍服，反映民族服饰交融。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('20', '广州南越王墓丝织品', '秦汉', '广东广州', '23.13', '113.26', '南越王博物院', '/images/relics/relic_geo_nanyue_silvyuyi.png', '南越王赵眜墓出土丝织品残片，绣有卷云纹、菱纹，为岭南地区汉代织绣提供实物依据。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('21', '都兰热水血渭一号大墓织锦', '隋唐', '青海都兰', '36.42', '98.09', '都兰县博物馆', '/images/relics/relic_geo_dulan_zhijin.png', '吐蕃时期都兰大墓出土缂丝、织金锦，图案含异域元素，见证丝路青海道织造交流。');
INSERT INTO relics (id, name, dynasty, location, geo_lat, geo_lng, museum, image_url, description) VALUES ('22', '定陵孝靖皇后百子衣', '明', '北京昌平', '40.3', '116.22', '明十三陵博物馆', '/images/relics/relic_geo_baiziyi_ming.png', '孝靖皇后刺绣百子衣以缂丝刺绣百名童子嬉戏纹样，织绣精绝，为明代宫廷礼服代表。');
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('1', '深衣', '先秦', '袍服', '士大夫', '文献', '丝·麻·褐', '黻纹·回纹', '玄纁', '', '《礼记·深衣》所载交领右衽长衣，短毋见肤长毋被土', '6', '2026-09-30 07:33:54', '/images/relics/relic_xianqin_shenyi.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('2', '素纱单衣', '秦汉', '袍服', '贵族女性', '出土', '素纱', '云气纹', '素白', '', '马王堆出土，重49克，汉代轻纱工艺巅峰', '1', '2026-09-30 07:33:54', '/images/relics/relic_han_susha.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('3', '曲裾深衣', '秦汉', '下裳', '贵族', '出土', '缣·绮', '云气纹', '尚红', '', '汉代曲裾绕襟，等级标识鲜明', '1', '2026-09-30 07:33:54', '/images/relics/relic_han_quju.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('4', '宽衫大袖', '魏晋', '袍服', '名士', '图像', '纱·罗', '忍冬纹', '素白', '', '《洛神赋图》宽衣博带之姿，玄学审美', NULL, '2026-09-30 07:33:54', '/images/relics/relic_weijin_kuanshan.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('5', '大袖襦裙', '隋唐', '下裳', '宫廷女性', '图像', '锦·绫·纱', '宝相花', '绯红', '', '《簪花仕女图》典型唐代女性盛装', '4', '2026-09-30 07:33:54', '/images/relics/relic_tang_ruqun.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('6', '圆领袍', '隋唐', '袍服', '官员', '图像', '绫·罗', '联珠纹', '明黄', '', '胡服改制的唐代官服常制', '4', '2026-09-30 07:33:54', '/images/relics/relic_tang_yuanling.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('7', '褙子', '宋', '袍服', '女子', '出土', '罗·纱·绢', '折枝花', '天水碧', '', '直领对襟两侧开衩，宋代典型外衣', '2', '2026-09-30 07:33:54', '/images/relics/relic_song_beizi.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('8', '质孙服', '元', '袍服', '蒙古贵族', '文献', '纳石失', '八宝纹', '金·蓝', '', '元代宫廷一色服制，织金锦为贵', '5', '2026-09-30 07:33:54', '/images/relics/relic_yuan_zhisun.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('9', '马面裙', '明', '下裳', '女性', '出土', '妆花缎', '缠枝莲', '正色', '', '两侧打褶前后裙门平整，明代典型裙式', '3', '2026-09-30 07:33:54', '/images/relics/relic_ming_maqun.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('10', '旗装', '清', '袍服', '满族女性', '传世', '绸·缎·缂丝', '团花纹', '宝蓝', '', '清代旗装立领盘扣，满汉服饰并存', NULL, '2026-09-30 07:33:54', '/images/relics/relic_qing_qizhuang.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('11', '上衣下裳', '上古', '袍服', '先民·贵族', '文献', '葛·麻·丝', '云雷纹·黻纹', '玄色·素白', NULL, '《周易·系辞》载"黄帝尧舜垂衣裳而天下治"，上衣下裳为华夏衣制之始：上衣象天、下裳象地，深衣与后世诸制皆由此演化。', NULL, NULL, '/images/dynasty_shanggu.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('12', '冕服', '先秦', '袍服', '天子·诸侯', '文献', '帛·皮', '十二章纹', '玄衣纁裳', NULL, '《周礼·司服》"王之吉服，祀昊天上帝则服大裘而冕"。十二章纹（日、月、星辰、山、龙、华虫等）自此成为历代帝王最高礼服的制度核心，明兴献帝画像犹见其制。', NULL, NULL, '/images/relics/relic_xianqin_mianfu.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('13', '凤鸟纹绣绢䋺衣', '先秦', '袍服', '楚国贵族', '出土', '绢·刺绣', '凤鸟纹·蟠螭纹', '赭红·玄褐', NULL, '湖北江陵马山一号楚墓出土战国丝袍：凤鸟相蟠纹绣于绢面、锦缘镶边，色彩瑰丽，是楚国"衣被天下"织绣工艺的直接物证。', '6', NULL, '/images/relics/relic_xianqin_fengniaoxiu.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('14', '信期绣绵袍', '秦汉', '袍服', '长沙国贵族', '出土', '罗地·锦缘', '信期绣·菱纹', '茶黄·褐', NULL, '马王堆一号汉墓出土丝绵袍，衣长150厘米、通袖250厘米。信期绣以穗状流云与卷曲蔓草为骨，与乘云绣、长寿绣并称马王堆三大名绣。', '7', NULL, '/images/relics/relic_han_xinqixiu.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('15', '印花敷彩丝绵袍', '秦汉', '袍服', '辛追墓随葬', '出土', '印花敷彩纱', '藤本植物纹', '朱红·粉白·墨黑', NULL, '马王堆一号汉墓出土，交领右衽直裾式，身长129厘米、袖通250厘米。印花与手工彩绘结合，是西汉服饰染织工艺的巅峰之作。', '8', NULL, '/images/relics/relic_han_yinhuafucai.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('16', '魏晋襦裙', '魏晋', '下裳', '贵族女性', '图像', '纱·罗', '忍冬纹·花卉纹', '素白·浅青', NULL, '顾恺之《女史箴图》中贵族女性着宽大衣裙，下摆曳地、飘带垂绦，配合"宽衣博带"风尚，体现魏晋玄学审美下的飘逸气韵。', NULL, NULL, '/images/relics/relic_weijin_ruqun.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('17', '裲裆', '魏晋', '上衣', '将士·武士', '图像', '布·铁·皮', '素面·鳞纹', '玄黑·褐', NULL, '南北朝武士所着"两当"：前后各一片护身背心，外穿于褶衣之上，见于邓县画像砖与武士陶俑，是魏晋南北朝尚武风尚的服饰标志。', NULL, NULL, '/images/relics/relic_weijin_liangdang.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('18', '半臂', '隋唐', '上衣', '男女通用', '图像', '锦·绫·纱', '宝相花·联珠纹', '绯红·靛青', NULL, '由半袖短衣演化、受胡服影响而成，隋唐女子时髦装束：外着短袖半臂、内衬长袖衫，唐永泰公主墓、燕德妃墓壁画侍女均如此装扮。', NULL, NULL, '/images/relics/relic_tang_banbi.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('19', '胡服·缺胯袍', '隋唐', '袍服', '胡人·唐人', '图像', '织锦·绫', '联珠纹·团窠纹', '五彩', NULL, '唐章怀太子墓《客使图》绘东罗马、新罗、靺鞨使节着翻领紫袍、骨苏冠、皮帽大氅等异域服制，是唐与三百余国交往、胡汉服饰交融的直接见证。', NULL, NULL, '/images/relics/relic_tang_hufu.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('20', '幞头', '隋唐', '首服', '男子通用', '图像', '罗·帛', '素面·展脚', '玄黑', NULL, '唐代男子最通行首服：以皂罗裹头、四脚系结，上至帝王下至庶民通戴。懿德太子墓、章怀太子墓壁画仪卫皆戴幞头穿圆领袍，为唐代"袍衫幞头"服制的标准形象。', NULL, NULL, '/images/relics/relic_tang_futou.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('21', '大袖·礼衣', '宋', '袍服', '命妇', '图像', '罗·绢·织绣', '摇翟纹·花钗', '深蓝·绛紫', NULL, '《宋史·舆服志》载命妇礼服制度；《宋宁宗后坐像》所绘交领大袖五彩褘衣，绣雉翟之纹、配花钗礼冠，为宋代宫廷命妇盛装的存世图像。', NULL, NULL, '/images/relics/relic_song_daxiu.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('22', '朱子深衣', '宋', '袍服', '士人', '文献', '布·绢', '素面·黻领', '玄色·素白', NULL, '朱熹据《礼记·深衣》与《家礼》考定复原：上衣四幅象四季、下裳十二片象十二月，袖圆以应规、交领矩以应方，背缝垂直喻正直，深衣制度由此成为后世礼服典范。', NULL, NULL, '/images/relics/relic_song_zhuzishenyi.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('23', '辫线袄', '元', '袍服', '蒙古男子', '出土', '绫·绢·织金', '八宝纹·云纹', '织金·褐', NULL, '元代蒙古男子袍服：交领窄袖，腰部以辫线收束，腰下打细褶如裙，便于骑射。河北隆化鸽子洞出土实物藏于中国丝绸博物馆。', '9', NULL, '/images/relics/relic_yuan_bianxianao.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('24', '姑姑冠', '元', '首服', '蒙古贵妇', '图像', '木·毡·珠玉', '珠宝花饰', '各色', NULL, '罟罟冠（姑姑冠）：以木为骨、包红绢金帛，顶插四五尺柳枝或铁枝，为蒙古已婚贵妇的身份标志，故宫藏元代皇后画像即戴此冠。', NULL, NULL, '/images/relics/relic_yuan_guguguan.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('25', '道袍', '明', '袍服', '士人·文人', '图像', '绫·绸', '暗花·云纹', '素色·玄黑', NULL, '明代士人常服：交领右衽、宽袖长身，腰束丝绦或太带。明代文人肖像画中随处可见，为晚明"曳撒、道袍、直身"男装体系的核心款式。', NULL, NULL, '/images/relics/relic_ming_daopao.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('26', '补服·官服', '明', '袍服', '品官', '图像', '缎·织金', '补子（禽兽纹）', '绯·青·绿', NULL, '明代以"补子"定品级：文官绣禽、武官绣兽，一品仙鹤、二品孔雀……官服服色四品以上绯、七品以上青、以下绿，乌纱帽为官员标识。', NULL, NULL, '/images/relics/relic_ming_bufu.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('27', '袄裙', '明', '下裳', '女性', '出土', '纱·绫', '花鸟纹·缠枝莲', '桃红·藕色', NULL, '明代女装"上衣下裙"组合：短袄（衫）配长裙。孔府旧藏桃红纱地彩绣花鸟纹大袖衫即为明代大袖衫实物，是"袄裙"体系的贵族版本。', '10', NULL, '/images/relics/relic_ming_aoqun.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('28', '马褂', '清', '上衣', '男子·后妃', '传世', '缎·绸·织金', '团花纹·事事如意', '湖色·明黄', NULL, '故宫藏湖色团花事事如意织金缎绵马褂（清宫旧藏）：圆立领、对襟、平袖、左右及后开裾，湖色冰梅纹暗花缎地织金柿蒂纹，谐寓"事事如意"，为皇帝便服。', NULL, NULL, '/images/relics/relic_qing_magua.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('29', '氅衣', '清', '袍服', '后妃', '传世', '缂丝·缎', '蝠寿纹·花蝶纹', '绿·绛色', NULL, '故宫藏绿色缂金银万字地蝠寿纹棉氅衣（清光绪）：圆领、大襟右衽、平端袖、左右开裾至腋下的直身式袍服，絮薄棉，为清宫后妃冬季便服。', NULL, NULL, '/images/relics/relic_qing_changyi.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('30', '坎肩', '清', '上衣', '男女', '传世', '缎·锦', '团牡丹·暗八仙', '石青·藏蓝', NULL, '故宫藏石青色团牡丹暗八仙纹一字襟坎肩：圆立领、一字襟，缀铜鎏金"禄"字扣十三颗（十三太保），织金团牡丹、卍字与暗八仙纹，清代满族服饰代表。', NULL, NULL, '/images/relics/relic_qing_kanjian.png', NULL);
INSERT INTO costumes (id, name, dynasty, category, wearer, source_type, fabric, pattern, color, shape_json, description, relic_id, create_time, image_url, created_by) VALUES ('31', '齐胸襦裙', '隋唐', '', '宝相花 · 忍冬纹', '用户创建', '', '', '', '', '', NULL, '2026-10-01 05:20:51', '', '3');
